 const filterButtons = Array.from(document.querySelectorAll(".filter-chip"));
 const productCards = Array.from(document.querySelectorAll(".product-card"));
 const filterStatus = document.querySelector("#filter-status");
 const cartStatus = document.querySelector("#cart-status");
 const countdown = document.querySelector("#countdown");
 const currentYear = document.querySelector("#current-year");
 const newsletterForm = document.querySelector(".newsletter-form");
 const emailInput = document.querySelector("#email");
 const emailError = document.querySelector("#email-error");

 if (currentYear) {
   currentYear.textContent = new Date().getFullYear().toString();
 }

 const filterLabels = {
   all: "all featured products",
   living: "living products",
   fashion: "fashion products",
   travel: "travel products",
 };

 filterButtons.forEach((button) => {
   button.addEventListener("click", () => {
     const { filter } = button.dataset;

     filterButtons.forEach((chip) => {
       const isActive = chip === button;
       chip.classList.toggle("is-active", isActive);
       chip.setAttribute("aria-pressed", String(isActive));
     });

     productCards.forEach((card) => {
       const matches = filter === "all" || card.dataset.category === filter;
       card.hidden = !matches;
     });

     if (filterStatus && filter) {
       filterStatus.textContent = `Showing ${filterLabels[filter]}.`;
     }
   });
 });

 document.querySelectorAll(".product-button").forEach((button) => {
   button.addEventListener("click", () => {
     const productName = button.getAttribute("data-product");

     if (cartStatus && productName) {
       cartStatus.textContent = `${productName} added to bag.`;
     }
   });
 });

 if (countdown) {
   const deadline = Date.now() + 12 * 60 * 60 * 1000;

   const updateCountdown = () => {
     const remaining = Math.max(deadline - Date.now(), 0);
     const hours = Math.floor(remaining / (1000 * 60 * 60));
     const minutes = Math.floor((remaining % (1000 * 60 * 60)) / (1000 * 60));

     countdown.textContent = `${hours}h ${minutes.toString().padStart(2, "0")}m`;
   };

   updateCountdown();
   window.setInterval(updateCountdown, 60000);
 }

 if (newsletterForm && emailInput && emailError) {
   const clearError = () => {
     emailInput.removeAttribute("aria-invalid");
     emailError.hidden = true;
   };

   emailInput.addEventListener("input", () => {
     if (emailInput.validity.valid) {
       clearError();
     }
   });

   newsletterForm.addEventListener("submit", (event) => {
     event.preventDefault();

     if (!emailInput.validity.valid) {
       emailInput.setAttribute("aria-invalid", "true");
       emailError.hidden = false;
       emailInput.focus();
       return;
     }

     clearError();
     newsletterForm.reset();

     if (cartStatus) {
       cartStatus.textContent = "Thanks for joining Northstar. Your first update is on the way.";
     }
   });
 }

